-- Nexmark q18 on clink, UPSERT-SINK sink variant. Latest bid per
-- bidder/auction pair: deduplication by ROW_NUMBER = 1 over a descending time
-- order. Unbounded keyspace, one retained row per key. The ORDER BY is made
-- TOTAL for the same reason as q5 and q19: two bids by one bidder on one
-- auction in the same millisecond have no defined 'latest', and each engine
-- would retain an arbitrary one. price then url break the tie - together with
-- the partition key and datetime they identify a bid in this dataset.
-- GENERATED by queries/gen_queries.py from the single cross-engine
-- definition. Edit that file, not this one.
CREATE TABLE bid (auction BIGINT, bidder BIGINT, price BIGINT, channel VARCHAR, url VARCHAR, datetime BIGINT)
  WITH (connector='kafka', format='json', brokers='__BROKERS__', topic='nx-bid',
        group_id='clink-q18up-bid', auto_offset_reset='earliest',
        event_time_column='datetime', watermark_lag_ms='4000');
CREATE TABLE sink_q18 (auction BIGINT, bidder BIGINT, price BIGINT, channel VARCHAR, url VARCHAR, datetime BIGINT)
  WITH (connector='kafka', format='json', brokers='__BROKERS__', topic='__OUT__',
        mode='upsert', primary_key='bidder,auction');
INSERT INTO sink_q18
SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY bidder, auction ORDER BY datetime DESC, price DESC, url DESC) AS rn FROM bid) AS R WHERE rn = 1;
